/* 15 search */
.pal{width:100%;max-width:440px;background:var(--panel);border:1px solid var(--icon-line)}
.pal-in{display:flex;align-items:center;gap:10px;padding:12px 14px;border-bottom:1px solid var(--line)}
.pal-in .ms{color:var(--muted)}
.pal-in input{flex:1;min-width:0;background:transparent;border:0;outline:0;color:var(--text);font:inherit;font-size:15px}
.pal-in input::placeholder{color:var(--muted)}
.pal-list{position:relative;padding:6px}
.pal-hl{position:absolute;left:6px;right:6px;top:0;height:0;background:var(--accent-bg);box-shadow:inset 2px 0 0 var(--accent);transition:transform .3s var(--ease),height .3s var(--ease),opacity .2s;pointer-events:none}
.pal-it{position:relative;display:flex;align-items:center;gap:12px;width:100%;padding:9px 10px;font-size:14px;color:var(--text-dim);text-align:left;transition:color .2s}
.pal-it.act{color:var(--accent)}
.pal-it .kbd{margin-left:auto;opacity:0;transition:opacity .2s}
.pal-it.act .kbd{opacity:1}
.pal-it mark{background:transparent;color:var(--text);font-weight:600}
.pal-it.act mark{color:var(--accent)}
.pal-empty{padding:26px 14px;text-align:center}
.pal-empty .t{font-weight:600;font-size:14px}
.pal-empty .d{margin-top:4px;font-size:13px;color:var(--muted)}
.pal-foot{display:flex;gap:14px;padding:10px 14px;border-top:1px solid var(--line)}
.pal-foot span{display:inline-flex;align-items:center;gap:6px;font-size:12px;color:var(--muted)}

/* ---------- 15 search ---------- */
{
  const q = $('#pal-q'), list = $('#pal-list'), hl = $('#pal-hl');
  const items = [
    ['dashboard','Open pricing page frame','Figma'],
    ['code','Export spacing tokens','Action'],
    ['description','Onboarding research summary','PDF'],
    ['grid_on','Compare token usage across frames','Action'],
    ['edit_note','Draft handoff notes','Action'],
    ['person','Find the web team','People']
  ];
  let shown = [], idx = 0;
  function render(){
    const v = q.value.trim().toLowerCase();
    shown = items.filter(i => i[1].toLowerCase().includes(v)); idx = 0;
    morph(list.parentElement, () => {
      $$('.pal-it,.pal-empty,.mono-xs', list).forEach(n => n.remove());
      if (!shown.length){
        const e = document.createElement('div'); e.className = 'pal-empty enter';
        e.innerHTML = `<div class="t">No results for "${q.value.replace(/[<>&"]/g,'')}"</div><div class="d">Try a file, component or action name</div>`;
        list.appendChild(e); hl.style.opacity = '0'; return;
      }
      const h = document.createElement('div'); h.className = 'mono-xs'; h.style.cssText = 'font-size:10px;padding:6px 10px'; h.textContent = v ? 'Results' : 'Suggestions'; list.appendChild(h);
      shown.forEach((it, i) => {
        const b = document.createElement('button'); b.className = 'pal-it';
        const label = v ? it[1].replace(new RegExp('(' + v.replace(/[.*+?^${}()|[\]\\]/g,'\\$&') + ')','i'), '<mark>$1</mark>') : it[1];
        b.innerHTML = `${ic(it[0],'sm')}<span>${label}</span><span class="kbd">${it[2]}</span>`;
        b.addEventListener('mouseenter', () => { idx = i; paint(); });
        b.addEventListener('click', () => open());
        list.appendChild(b);
      });
    });
    requestAnimationFrame(paint);
  }
  function paint(){ const its = $$('.pal-it', list); its.forEach((b, i) => b.classList.toggle('act', i === idx)); glide(hl, its[idx], list); }
  function open(){ if (!shown[idx]) return; Sound.play('select'); showToast('Opened: ' + shown[idx][1]); }
  let lastLen = 0;
  q.addEventListener('input', () => { render(); if (q.value.length > lastLen) Sound.play('stream'); lastLen = q.value.length; });
  q.addEventListener('keydown', e => {
    if (e.key === 'ArrowDown' || e.key === 'ArrowUp'){ e.preventDefault(); if (!shown.length) return; idx = (idx + (e.key === 'ArrowDown' ? 1 : -1) + shown.length) % shown.length; paint(); Sound.play('tick'); }
    else if (e.key === 'Enter'){ e.preventDefault(); open(); }
    else if (e.key === 'Escape'){ q.value = ''; render(); Sound.play('close'); }
  });
  render();
}
